import openpyxl
wb=openpyxl.load_workbook('output.xlsx',data_only=True)
ws=wb['Sheet1']
# grid values
goal={'J':[ws.cell(r,10).value for r in range(3,7)],'K':[ws.cell(r,11).value for r in range(3,7)],'L':[ws.cell(r,12).value for r in range(3,7)],'M':[ws.cell(r,13).value for r in range(3,7)]}
m2={'P':[ws.cell(r,16).value for r in range(3,7)],'Q':[ws.cell(r,17).value for r in range(3,7)],'R':[ws.cell(r,18).value for r in range(3,7)],'S':[ws.cell(r,19).value for r in range(3,7)],'T':[ws.cell(r,20).value for r in range(3,7)]}
def vrow(v):
    if v<0.03: return 0
    if v<0.05: return 1
    if v<0.07: return 2
    return 3
def gcol(g):
    for i,b in enumerate([0.65,0.75,0.85,0.95]):
        if g<b: return ['J','K','L','M'][i]
    return 'M'
def mcol(m):
    for i,b in enumerate([-0.2,-0.1,0,0.1,0.2]):
        if m<b: return ['P','Q','R','S','T'][i]
    return 'T'
for r in range(2,20):
    g=ws.cell(r,4).value; e=ws.cell(r,5).value; m=ws.cell(r,6).value
    rv=vrow(e); gc=gcol(g); mc=mcol(m)
    val=goal[gc][rv]+m2[mc][rv]
    print(r, round(val,4))
"
